//! C ABI of the `AudioServerPlugIn`, laid out after `AudioServerPlugInDriverInterface` in Apple's
//! public SDK header `CoreAudio/AudioServerPlugIn.h` (not generated by `objc2-core-audio`).
//!
//! Every entry point is a thin translation into [`Driver`] and the property [`model`], wrapped
//! in `catch_unwind` so a bug can never unwind into `coreaudiod`.

mod values;

use std::ffi::c_void;
use std::panic::{AssertUnwindSafe, catch_unwind};
use std::ptr::NonNull;
use std::sync::OnceLock;
use std::sync::atomic::{AtomicU32, Ordering};

use objc2_core_audio::{
    AudioGetCurrentHostTime, AudioGetHostClockFrequency, AudioObjectPropertyAddress,
    AudioServerPlugInClientInfo,
};
use objc2_core_audio_types::AudioTimeStamp;
use objc2_core_foundation::{CFUUID, CFUUIDBytes, HRESULT, LPVOID, REFIID, ULONG};

use crate::driver::Driver;
use crate::model::{self, DeviceKind, Object};
use crate::selectors as sel;

type OsStatus = i32;
type Boolean = u8;
type DriverRef = *mut c_void;
type Pid = i32;

/// `kAudioServerPlugInTypeUUID` 443ABAB8-E7B3-491A-B985-BEB9187030DB.
const PLUGIN_TYPE_UUID: [u8; 16] = [
    0x44, 0x3A, 0xBA, 0xB8, 0xE7, 0xB3, 0x49, 0x1A, 0xB9, 0x85, 0xBE, 0xB9, 0x18, 0x70, 0x30, 0xDB,
];
/// `kAudioServerPlugInDriverInterfaceUUID` EEA5773D-CC43-49F1-8E00-8F96E7D23B17.
const DRIVER_INTERFACE_UUID: [u8; 16] = [
    0xEE, 0xA5, 0x77, 0x3D, 0xCC, 0x43, 0x49, 0xF1, 0x8E, 0x00, 0x8F, 0x96, 0xE7, 0xD2, 0x3B, 0x17,
];
/// `IUnknownUUID` 00000000-0000-0000-C000-000000000046.
const IUNKNOWN_UUID: [u8; 16] = [
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xC0, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x46,
];
/// COM `E_NOINTERFACE`.
#[allow(clippy::cast_possible_wrap)] // the COM constant is defined as this bit pattern
const E_NOINTERFACE: HRESULT = 0x8000_0004_u32 as HRESULT;

/// `AudioServerPlugInIOCycleInfo` (not generated by `objc2-core-audio`).
#[repr(C)]
struct IoCycleInfo {
    io_cycle_counter: u64,
    nominal_io_buffer_frame_size: u32,
    current_time: AudioTimeStamp,
    input_time: AudioTimeStamp,
    output_time: AudioTimeStamp,
    main_host_ticks_per_frame: f64,
    device_host_ticks_per_frame: f64,
}

type Address = *const AudioObjectPropertyAddress;
type ClientInfo = *const AudioServerPlugInClientInfo;

/// `AudioServerPlugInDriverInterface`: the COM-style vtable the HAL calls.
#[repr(C)]
struct DriverInterface {
    reserved: *mut c_void,
    query_interface: unsafe extern "C" fn(*mut c_void, REFIID, *mut LPVOID) -> HRESULT,
    add_ref: unsafe extern "C" fn(*mut c_void) -> ULONG,
    release: unsafe extern "C" fn(*mut c_void) -> ULONG,
    initialize: unsafe extern "C" fn(DriverRef, *const c_void) -> OsStatus,
    create_device: unsafe extern "C" fn(DriverRef, *const c_void, ClientInfo, *mut u32) -> OsStatus,
    destroy_device: unsafe extern "C" fn(DriverRef, u32) -> OsStatus,
    add_device_client: unsafe extern "C" fn(DriverRef, u32, ClientInfo) -> OsStatus,
    remove_device_client: unsafe extern "C" fn(DriverRef, u32, ClientInfo) -> OsStatus,
    perform_device_configuration_change:
        unsafe extern "C" fn(DriverRef, u32, u64, *mut c_void) -> OsStatus,
    abort_device_configuration_change:
        unsafe extern "C" fn(DriverRef, u32, u64, *mut c_void) -> OsStatus,
    has_property: unsafe extern "C" fn(DriverRef, u32, Pid, Address) -> Boolean,
    is_property_settable:
        unsafe extern "C" fn(DriverRef, u32, Pid, Address, *mut Boolean) -> OsStatus,
    get_property_data_size: unsafe extern "C" fn(
        DriverRef,
        u32,
        Pid,
        Address,
        u32,
        *const c_void,
        *mut u32,
    ) -> OsStatus,
    get_property_data: unsafe extern "C" fn(
        DriverRef,
        u32,
        Pid,
        Address,
        u32,
        *const c_void,
        u32,
        *mut u32,
        *mut c_void,
    ) -> OsStatus,
    set_property_data: unsafe extern "C" fn(
        DriverRef,
        u32,
        Pid,
        Address,
        u32,
        *const c_void,
        u32,
        *const c_void,
    ) -> OsStatus,
    start_io: unsafe extern "C" fn(DriverRef, u32, u32) -> OsStatus,
    stop_io: unsafe extern "C" fn(DriverRef, u32, u32) -> OsStatus,
    get_zero_time_stamp:
        unsafe extern "C" fn(DriverRef, u32, u32, *mut f64, *mut u64, *mut u64) -> OsStatus,
    will_do_io_operation:
        unsafe extern "C" fn(DriverRef, u32, u32, u32, *mut Boolean, *mut Boolean) -> OsStatus,
    begin_io_operation:
        unsafe extern "C" fn(DriverRef, u32, u32, u32, u32, *const IoCycleInfo) -> OsStatus,
    do_io_operation: unsafe extern "C" fn(
        DriverRef,
        u32,
        u32,
        u32,
        u32,
        u32,
        *const IoCycleInfo,
        *mut c_void,
        *mut c_void,
    ) -> OsStatus,
    end_io_operation:
        unsafe extern "C" fn(DriverRef, u32, u32, u32, u32, *const IoCycleInfo) -> OsStatus,
}

/// Wrapper so the vtable (which contains a raw pointer) can live in a `static`.
#[repr(transparent)]
struct Shared<T>(T);
// SAFETY: the wrapped values are immutable after initialisation (function pointers and a null
// or static pointer), so sharing them between threads is sound.
unsafe impl<T> Sync for Shared<T> {}

static INTERFACE: Shared<DriverInterface> = Shared(DriverInterface {
    reserved: std::ptr::null_mut(),
    query_interface,
    add_ref,
    release,
    initialize,
    create_device,
    destroy_device,
    add_device_client,
    remove_device_client,
    perform_device_configuration_change: configuration_change,
    abort_device_configuration_change: configuration_change,
    has_property,
    is_property_settable,
    get_property_data_size,
    get_property_data,
    set_property_data,
    start_io,
    stop_io,
    get_zero_time_stamp,
    will_do_io_operation,
    begin_io_operation: io_bracket,
    do_io_operation,
    end_io_operation: io_bracket,
});

/// The `AudioServerPlugInDriverRef`: a pointer to a pointer to the vtable.
static DRIVER_REF: Shared<&DriverInterface> = Shared(&INTERFACE.0);

static REF_COUNT: AtomicU32 = AtomicU32::new(0);
static DRIVER: OnceLock<Driver> = OnceLock::new();

fn driver() -> &'static Driver {
    // SAFETY: plain CoreAudio query without arguments.
    DRIVER.get_or_init(|| Driver::new(unsafe { AudioGetHostClockFrequency() }))
}

fn driver_ref() -> *mut c_void {
    std::ptr::from_ref(&DRIVER_REF).cast_mut().cast()
}

/// Runs `body`, turning a panic into `fallback`.
fn guarded<T>(fallback: T, body: impl FnOnce() -> T) -> T {
    catch_unwind(AssertUnwindSafe(body)).unwrap_or(fallback)
}

fn uuid_bytes(bytes: CFUUIDBytes) -> [u8; 16] {
    [
        bytes.byte0,
        bytes.byte1,
        bytes.byte2,
        bytes.byte3,
        bytes.byte4,
        bytes.byte5,
        bytes.byte6,
        bytes.byte7,
        bytes.byte8,
        bytes.byte9,
        bytes.byte10,
        bytes.byte11,
        bytes.byte12,
        bytes.byte13,
        bytes.byte14,
        bytes.byte15,
    ]
}

fn device_kind(id: u32) -> Option<DeviceKind> {
    match Object::from_id(id)? {
        Object::Device(kind) => Some(kind),
        _ => None,
    }
}

/// `CFPlugIn` factory named in `Info.plist` (`CFPlugInFactories`).
///
/// # Safety
/// Called by CoreFoundation with a valid (or null) `CFUUIDRef`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn StealSeriesMic_Create(
    _allocator: *const c_void,
    requested_type: *const CFUUID,
) -> *mut c_void {
    guarded(std::ptr::null_mut(), || {
        // SAFETY: CoreFoundation passes a valid CFUUID or null.
        let Some(requested) = (unsafe { requested_type.as_ref() }) else {
            return std::ptr::null_mut();
        };
        if uuid_bytes(requested.uuid_bytes()) != PLUGIN_TYPE_UUID {
            return std::ptr::null_mut();
        }
        let _ = driver();
        REF_COUNT.fetch_add(1, Ordering::AcqRel);
        driver_ref()
    })
}

unsafe extern "C" fn query_interface(
    _driver: *mut c_void,
    uuid: REFIID,
    out: *mut LPVOID,
) -> HRESULT {
    guarded(E_NOINTERFACE, || {
        let Some(out) = NonNull::new(out) else {
            return E_NOINTERFACE;
        };
        let requested = uuid_bytes(uuid);
        if requested != IUNKNOWN_UUID && requested != DRIVER_INTERFACE_UUID {
            // SAFETY: `out` is a valid out-pointer supplied by the host.
            unsafe { out.write(std::ptr::null_mut()) };
            return E_NOINTERFACE;
        }
        REF_COUNT.fetch_add(1, Ordering::AcqRel);
        // SAFETY: as above.
        unsafe { out.write(driver_ref()) };
        0
    })
}

unsafe extern "C" fn add_ref(_driver: *mut c_void) -> ULONG {
    REF_COUNT.fetch_add(1, Ordering::AcqRel).saturating_add(1)
}

unsafe extern "C" fn release(_driver: *mut c_void) -> ULONG {
    // The driver is static; the count is informational only and never frees anything.
    let mut current = REF_COUNT.load(Ordering::Acquire);
    loop {
        let next = current.saturating_sub(1);
        match REF_COUNT.compare_exchange_weak(current, next, Ordering::AcqRel, Ordering::Acquire) {
            Ok(_) => return next,
            Err(actual) => current = actual,
        }
    }
}

unsafe extern "C" fn initialize(_driver: DriverRef, _host: *const c_void) -> OsStatus {
    guarded(sel::STATUS_UNSPECIFIED, || {
        let _ = driver();
        sel::STATUS_OK
    })
}

unsafe extern "C" fn create_device(
    _driver: DriverRef,
    _description: *const c_void,
    _client: ClientInfo,
    _out: *mut u32,
) -> OsStatus {
    sel::STATUS_UNSUPPORTED_OPERATION
}

unsafe extern "C" fn destroy_device(_driver: DriverRef, _device: u32) -> OsStatus {
    sel::STATUS_UNSUPPORTED_OPERATION
}

unsafe extern "C" fn add_device_client(
    _driver: DriverRef,
    device: u32,
    _client: ClientInfo,
) -> OsStatus {
    status_for_device(device)
}

unsafe extern "C" fn remove_device_client(
    _driver: DriverRef,
    device: u32,
    _client: ClientInfo,
) -> OsStatus {
    status_for_device(device)
}

unsafe extern "C" fn configuration_change(
    _driver: DriverRef,
    device: u32,
    _action: u64,
    _info: *mut c_void,
) -> OsStatus {
    status_for_device(device)
}

fn status_for_device(device: u32) -> OsStatus {
    if device_kind(device).is_some() {
        sel::STATUS_OK
    } else {
        sel::STATUS_BAD_DEVICE
    }
}

/// Looks up the property value for `object`/`address`.
fn lookup(object: u32, address: Address) -> Result<model::PropertyValue, OsStatus> {
    let object = Object::from_id(object).ok_or(sel::STATUS_BAD_OBJECT)?;
    // SAFETY: the HAL passes a valid property address.
    let address = unsafe { address.as_ref() }.ok_or(sel::STATUS_ILLEGAL_OPERATION)?;
    model::property(object, address.mSelector, address.mScope, driver().state())
        .ok_or(sel::STATUS_UNKNOWN_PROPERTY)
}

unsafe extern "C" fn has_property(
    _driver: DriverRef,
    object: u32,
    _pid: Pid,
    address: Address,
) -> Boolean {
    guarded(0, || Boolean::from(lookup(object, address).is_ok()))
}

unsafe extern "C" fn is_property_settable(
    _driver: DriverRef,
    object: u32,
    _pid: Pid,
    address: Address,
    out_settable: *mut Boolean,
) -> OsStatus {
    guarded(sel::STATUS_UNSPECIFIED, || {
        if let Err(status) = lookup(object, address) {
            return status;
        }
        let Some(out) = NonNull::new(out_settable) else {
            return sel::STATUS_ILLEGAL_OPERATION;
        };
        // SAFETY: valid out-pointer from the host. Nothing is settable (fixed format).
        unsafe { out.write(0) };
        sel::STATUS_OK
    })
}

unsafe extern "C" fn get_property_data_size(
    _driver: DriverRef,
    object: u32,
    _pid: Pid,
    address: Address,
    _qualifier_size: u32,
    _qualifier: *const c_void,
    out_size: *mut u32,
) -> OsStatus {
    guarded(sel::STATUS_UNSPECIFIED, || {
        let value = match lookup(object, address) {
            Ok(value) => value,
            Err(status) => return status,
        };
        let Some(out) = NonNull::new(out_size) else {
            return sel::STATUS_ILLEGAL_OPERATION;
        };
        let size = u32::try_from(values::byte_size(&value)).unwrap_or(u32::MAX);
        // SAFETY: valid out-pointer from the host.
        unsafe { out.write(size) };
        sel::STATUS_OK
    })
}

unsafe extern "C" fn get_property_data(
    _driver: DriverRef,
    object: u32,
    _pid: Pid,
    address: Address,
    qualifier_size: u32,
    qualifier: *const c_void,
    data_size: u32,
    out_size: *mut u32,
    out_data: *mut c_void,
) -> OsStatus {
    guarded(sel::STATUS_UNSPECIFIED, || {
        let value = match lookup(object, address) {
            Ok(value) => value,
            Err(status) => return status,
        };
        let (Some(out_size), Some(out_data)) = (NonNull::new(out_size), NonNull::new(out_data))
        else {
            return sel::STATUS_ILLEGAL_OPERATION;
        };
        // SAFETY: the host provides `data_size` writable bytes at `out_data` and
        // `qualifier_size` readable bytes at `qualifier`.
        let written = unsafe {
            values::write(
                &value,
                out_data,
                data_size as usize,
                NonNull::new(qualifier.cast_mut()),
                qualifier_size as usize,
            )
        };
        match written {
            Ok(size) => {
                // SAFETY: valid out-pointer from the host.
                unsafe { out_size.write(u32::try_from(size).unwrap_or(u32::MAX)) };
                sel::STATUS_OK
            }
            Err(status) => status,
        }
    })
}

unsafe extern "C" fn set_property_data(
    _driver: DriverRef,
    object: u32,
    _pid: Pid,
    address: Address,
    _qualifier_size: u32,
    _qualifier: *const c_void,
    data_size: u32,
    data: *const c_void,
) -> OsStatus {
    guarded(sel::STATUS_UNSPECIFIED, || {
        if let Err(status) = lookup(object, address) {
            return status;
        }
        // SAFETY: `lookup` succeeded, so `address` is valid.
        let selector = unsafe { (*address).mSelector };
        let Some(data) = NonNull::new(data.cast_mut()) else {
            return sel::STATUS_ILLEGAL_OPERATION;
        };
        // SAFETY: the host provides `data_size` readable bytes.
        if unsafe { values::is_noop_set(selector, data, data_size as usize) } {
            sel::STATUS_OK
        } else {
            sel::STATUS_UNSUPPORTED_OPERATION
        }
    })
}

unsafe extern "C" fn start_io(_driver: DriverRef, device: u32, _client: u32) -> OsStatus {
    guarded(sel::STATUS_UNSPECIFIED, || {
        let Some(kind) = device_kind(device) else {
            return sel::STATUS_BAD_OBJECT;
        };
        // SAFETY: plain CoreAudio query without arguments.
        driver().start_io(kind, unsafe { AudioGetCurrentHostTime() });
        sel::STATUS_OK
    })
}

unsafe extern "C" fn stop_io(_driver: DriverRef, device: u32, _client: u32) -> OsStatus {
    guarded(sel::STATUS_UNSPECIFIED, || {
        let Some(kind) = device_kind(device) else {
            return sel::STATUS_BAD_OBJECT;
        };
        match driver().stop_io(kind) {
            Ok(()) => sel::STATUS_OK,
            Err(_) => sel::STATUS_ILLEGAL_OPERATION,
        }
    })
}

unsafe extern "C" fn get_zero_time_stamp(
    _driver: DriverRef,
    device: u32,
    _client: u32,
    out_sample_time: *mut f64,
    out_host_time: *mut u64,
    out_seed: *mut u64,
) -> OsStatus {
    guarded(sel::STATUS_UNSPECIFIED, || {
        if device_kind(device).is_none() {
            return sel::STATUS_BAD_OBJECT;
        }
        let (Some(sample), Some(host), Some(seed)) = (
            NonNull::new(out_sample_time),
            NonNull::new(out_host_time),
            NonNull::new(out_seed),
        ) else {
            return sel::STATUS_ILLEGAL_OPERATION;
        };
        // SAFETY: plain CoreAudio query without arguments.
        let stamp = driver().zero_time_stamp(unsafe { AudioGetCurrentHostTime() });
        // SAFETY: valid out-pointers from the host.
        unsafe {
            sample.write(stamp.sample_time);
            host.write(stamp.host_time);
            seed.write(crate::clock::TIMESTAMP_SEED);
        }
        sel::STATUS_OK
    })
}

unsafe extern "C" fn will_do_io_operation(
    _driver: DriverRef,
    device: u32,
    _client: u32,
    operation: u32,
    out_will_do: *mut Boolean,
    out_in_place: *mut Boolean,
) -> OsStatus {
    guarded(sel::STATUS_UNSPECIFIED, || {
        let Some(kind) = device_kind(device) else {
            return sel::STATUS_BAD_OBJECT;
        };
        let (Some(will_do), Some(in_place)) =
            (NonNull::new(out_will_do), NonNull::new(out_in_place))
        else {
            return sel::STATUS_ILLEGAL_OPERATION;
        };
        // SAFETY: valid out-pointers from the host.
        unsafe {
            will_do.write(Boolean::from(Driver::will_do(kind, operation)));
            in_place.write(1);
        }
        sel::STATUS_OK
    })
}

unsafe extern "C" fn io_bracket(
    _driver: DriverRef,
    device: u32,
    _client: u32,
    _operation: u32,
    _frames: u32,
    _cycle: *const IoCycleInfo,
) -> OsStatus {
    status_for_device(device)
}

unsafe extern "C" fn do_io_operation(
    _driver: DriverRef,
    device: u32,
    _stream: u32,
    _client: u32,
    operation: u32,
    frames: u32,
    cycle: *const IoCycleInfo,
    main_buffer: *mut c_void,
    _secondary_buffer: *mut c_void,
) -> OsStatus {
    guarded(sel::STATUS_UNSPECIFIED, || {
        let Some(kind) = device_kind(device) else {
            return sel::STATUS_BAD_OBJECT;
        };
        // SAFETY: the host passes a valid cycle description for the duration of the call.
        let (Some(cycle), Some(buffer)) = (unsafe { cycle.as_ref() }, NonNull::new(main_buffer))
        else {
            return sel::STATUS_OK;
        };
        let sample_time = match kind {
            DeviceKind::Mic => cycle.input_time.mSampleTime,
            DeviceKind::Feed => cycle.output_time.mSampleTime,
        };
        let samples = frames as usize * model::CHANNELS as usize;
        // SAFETY: the main buffer holds `frames` frames in our (mono f32) stream format and is
        // exclusively ours for the call.
        let buffer =
            unsafe { std::slice::from_raw_parts_mut(buffer.cast::<f32>().as_ptr(), samples) };
        driver().do_io(kind, operation, sample_time, buffer);
        sel::STATUS_OK
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn io_cycle_info_matches_the_c_layout() {
        // 8 + 4 (+4 padding) + 3 × 64 + 8 + 8 bytes in the SDK header.
        assert_eq!(size_of::<AudioTimeStamp>(), 64);
        assert_eq!(size_of::<IoCycleInfo>(), 8 + 8 + 3 * 64 + 8 + 8);
    }

    #[test]
    fn vtable_has_one_slot_per_header_entry() {
        // _reserved + 3 IUnknown + 19 driver functions in AudioServerPlugIn.h.
        assert_eq!(size_of::<DriverInterface>(), 23 * size_of::<usize>());
    }

    fn cf_bytes(b: [u8; 16]) -> CFUUIDBytes {
        CFUUIDBytes {
            byte0: b[0],
            byte1: b[1],
            byte2: b[2],
            byte3: b[3],
            byte4: b[4],
            byte5: b[5],
            byte6: b[6],
            byte7: b[7],
            byte8: b[8],
            byte9: b[9],
            byte10: b[10],
            byte11: b[11],
            byte12: b[12],
            byte13: b[13],
            byte14: b[14],
            byte15: b[15],
        }
    }

    fn address(selector: u32, scope: u32) -> AudioObjectPropertyAddress {
        AudioObjectPropertyAddress {
            mSelector: selector,
            mScope: scope,
            mElement: 0,
        }
    }

    /// Drives the plug-in through its vtable the way `coreaudiod` does, so contract errors
    /// show up here instead of crashing the audio server after installation.
    #[test]
    #[allow(clippy::too_many_lines)] // one scripted HAL session, step by step
    fn behaves_like_a_hal_plugin_through_the_vtable() {
        // SAFETY (whole test): all pointers passed are valid locals; the driver ref returned by
        // the factory points to the static vtable pointer.
        unsafe {
            let wrong = CFUUID::from_uuid_bytes(None, cf_bytes(IUNKNOWN_UUID)).unwrap();
            assert!(StealSeriesMic_Create(std::ptr::null(), &raw const *wrong).is_null());

            let plugin_type = CFUUID::from_uuid_bytes(None, cf_bytes(PLUGIN_TYPE_UUID)).unwrap();
            let driver = StealSeriesMic_Create(std::ptr::null(), &raw const *plugin_type);
            assert!(!driver.is_null());
            let vtable: &DriverInterface = *driver.cast::<&DriverInterface>();

            let mut interface: LPVOID = std::ptr::null_mut();
            let status = (vtable.query_interface)(
                driver,
                cf_bytes(DRIVER_INTERFACE_UUID),
                &raw mut interface,
            );
            assert_eq!((status, interface), (0, driver));
            assert_eq!((vtable.initialize)(driver, std::ptr::null()), 0);

            // Device list via size + data.
            let list = address(sel::PLUGIN_DEVICE_LIST, sel::SCOPE_GLOBAL);
            let mut size = 0_u32;
            let status = (vtable.get_property_data_size)(
                driver,
                model::PLUGIN_ID,
                0,
                &raw const list,
                0,
                std::ptr::null(),
                &raw mut size,
            );
            assert_eq!((status, size), (0, 8));
            let mut ids = [0_u32; 2];
            let status = (vtable.get_property_data)(
                driver,
                model::PLUGIN_ID,
                0,
                &raw const list,
                0,
                std::ptr::null(),
                8,
                &raw mut size,
                ids.as_mut_ptr().cast(),
            );
            assert_eq!(
                (status, ids),
                (0, [model::MIC_DEVICE_ID, model::FEED_DEVICE_ID])
            );

            // Device name as CFString (caller releases).
            let name = address(sel::NAME, sel::SCOPE_GLOBAL);
            let mut string: *const objc2_core_foundation::CFString = std::ptr::null();
            let status = (vtable.get_property_data)(
                driver,
                model::MIC_DEVICE_ID,
                0,
                &raw const name,
                0,
                std::ptr::null(),
                8,
                &raw mut size,
                (&raw mut string).cast(),
            );
            assert_eq!(status, 0);
            let string = objc2_core_foundation::CFRetained::from_raw(
                NonNull::new(string.cast_mut()).unwrap(),
            );
            assert_eq!(string.to_string(), "StealSeries Microphone");

            // UID → device with a CFString qualifier.
            let translate = address(sel::PLUGIN_TRANSLATE_UID_TO_DEVICE, sel::SCOPE_GLOBAL);
            let uid = objc2_core_foundation::CFString::from_str("dev.stealseries.mic.feed");
            let qualifier: *const objc2_core_foundation::CFString = &raw const *uid;
            let mut device = 0_u32;
            let status = (vtable.get_property_data)(
                driver,
                model::PLUGIN_ID,
                0,
                &raw const translate,
                8,
                (&raw const qualifier).cast(),
                4,
                &raw mut size,
                (&raw mut device).cast(),
            );
            assert_eq!((status, device), (0, model::FEED_DEVICE_ID));

            // Unknown property and object.
            let unknown = address(sel::fourcc(b"zzzz"), sel::SCOPE_GLOBAL);
            assert_eq!(
                (vtable.has_property)(driver, model::MIC_DEVICE_ID, 0, &raw const unknown),
                0
            );
            let status = (vtable.get_property_data_size)(
                driver,
                77,
                0,
                &raw const list,
                0,
                std::ptr::null(),
                &raw mut size,
            );
            assert_eq!(status, sel::STATUS_BAD_OBJECT);

            // Setting the sample rate to its current value is accepted, anything else is not.
            let rate = address(sel::DEVICE_NOMINAL_SAMPLE_RATE, sel::SCOPE_GLOBAL);
            let same = model::SAMPLE_RATE;
            let other = 44_100.0_f64;
            assert_eq!(
                (vtable.set_property_data)(
                    driver,
                    model::MIC_DEVICE_ID,
                    0,
                    &raw const rate,
                    0,
                    std::ptr::null(),
                    8,
                    (&raw const same).cast()
                ),
                0
            );
            assert_eq!(
                (vtable.set_property_data)(
                    driver,
                    model::MIC_DEVICE_ID,
                    0,
                    &raw const rate,
                    0,
                    std::ptr::null(),
                    8,
                    (&raw const other).cast()
                ),
                sel::STATUS_UNSUPPORTED_OPERATION
            );

            // IO: feed writes, mic reads the same sample time.
            assert_eq!((vtable.start_io)(driver, model::FEED_DEVICE_ID, 1), 0);
            assert_eq!((vtable.start_io)(driver, model::MIC_DEVICE_ID, 2), 0);
            let (mut sample_time, mut host_time, mut seed) = (0.0, 0_u64, 0_u64);
            assert_eq!(
                (vtable.get_zero_time_stamp)(
                    driver,
                    model::MIC_DEVICE_ID,
                    2,
                    &raw mut sample_time,
                    &raw mut host_time,
                    &raw mut seed
                ),
                0
            );
            assert_eq!(seed, crate::clock::TIMESTAMP_SEED);

            let (mut will_do, mut in_place) = (0_u8, 0_u8);
            assert_eq!(
                (vtable.will_do_io_operation)(
                    driver,
                    model::FEED_DEVICE_ID,
                    1,
                    sel::IO_WRITE_MIX,
                    &raw mut will_do,
                    &raw mut in_place
                ),
                0
            );
            assert_eq!((will_do, in_place), (1, 1));

            let mut cycle: IoCycleInfo = std::mem::zeroed();
            cycle.output_time.mSampleTime = 4096.0;
            cycle.input_time.mSampleTime = 4096.0;
            let mut written = [0.5_f32; 64];
            assert_eq!(
                (vtable.do_io_operation)(
                    driver,
                    model::FEED_DEVICE_ID,
                    model::FEED_STREAM_ID,
                    1,
                    sel::IO_WRITE_MIX,
                    64,
                    &raw const cycle,
                    written.as_mut_ptr().cast(),
                    std::ptr::null_mut()
                ),
                0
            );
            let mut read = [0.0_f32; 64];
            assert_eq!(
                (vtable.do_io_operation)(
                    driver,
                    model::MIC_DEVICE_ID,
                    model::MIC_STREAM_ID,
                    2,
                    sel::IO_READ_INPUT,
                    64,
                    &raw const cycle,
                    read.as_mut_ptr().cast(),
                    std::ptr::null_mut()
                ),
                0
            );
            assert_eq!(read, [0.5; 64]);

            assert_eq!((vtable.stop_io)(driver, model::MIC_DEVICE_ID, 2), 0);
            assert_eq!((vtable.stop_io)(driver, model::FEED_DEVICE_ID, 1), 0);
            assert_eq!(
                (vtable.stop_io)(driver, model::FEED_DEVICE_ID, 1),
                sel::STATUS_ILLEGAL_OPERATION
            );
            (vtable.release)(driver);
        }
    }
}
